-- No employee personal data in this migration.
alter table public.holidays add column locations text[] not null default '{}';
alter table public.employee_private_details add column birth_month integer, add column birth_day integer, add column work_phone text not null default '', add column phone_extension text not null default '';
alter table public.employee_private_details add constraint birthday_parts_valid check ((birth_month is null and birth_day is null) or (birth_month between 1 and 12 and birth_day between 1 and extract(day from (make_date(2000,birth_month,1)+interval '1 month - 1 day'))));
create or replace function public.calendar_birthdays(p_year integer) returns table(user_id uuid,full_name text,birthday date) language plpgsql stable security definer set search_path='' as $$begin
 perform private.assert_member();if p_year not between 1900 and 2200 then raise exception 'Invalid calendar year.';end if;
 return query select e.user_id,e.full_name,make_date(p_year,coalesce(d.birth_month,extract(month from d.dob)::integer),least(coalesce(d.birth_day,extract(day from d.dob)::integer),extract(day from (make_date(p_year,coalesce(d.birth_month,extract(month from d.dob)::integer),1)+interval '1 month - 1 day'))::integer)) from public.employees e join public.employee_private_details d on d.employee_id=e.id where e.archived_at is null and coalesce(e.departure_status,'Active') not in ('Left','Terminated') and (d.dob is not null or d.birth_month is not null);end;$$;
